import {searchProjects} from './matcher.js';
export function fallbackConcept(type,idea,projects){const systems={Website:['Content structure','Responsive pages','Enquiry flow','Content management'],'Mobile App':['Mobile navigation','Core user workflow','Local preferences','Release preparation'],AI:['Input workflow','AI service integration','Output review','Usage controls'],Marketplace:['Customer accounts','Supplier listings','Search and filters','Admin dashboard'],'Booking Platform':['Availability calendar','Booking requests','Customer notifications','Booking administration'],'E-commerce':['Product catalogue','Shopping cart','Checkout integration','Order management'],'Something Crazy':['Concept validation','Interactive prototype','Core experience','Feedback collection']};const core=systems[type]||systems.Website;const matches=searchProjects(type+' '+idea,projects).projects;return{projectName:`Your ${type.toLowerCase()} concept`,summary:idea,productType:type,coreSystems:core,suggestedPhases:[{name:'MVP',items:core.slice(0,3)},{name:'Phase 2',items:[core[3],'Refine based on user feedback']}],complexity:null,matchingProjectIds:matches.map(p=>p.id),nextStep:'Discuss the scope, users and requirements with DevMania.'}}
export function validConcept(x,projects){
 const text=(v,max)=>typeof v==='string'&&v.trim().length>0&&v.length<=max;
 const list=(v,max,n)=>Array.isArray(v)&&v.length>0&&v.length<=n&&v.every(s=>text(s,max));
 return !!(x&&typeof x==='object'&&!Array.isArray(x)&&text(x.projectName,160)&&text(x.summary,4000)&&text(x.productType,80)&&list(x.coreSystems,250,12)&&Array.isArray(x.suggestedPhases)&&x.suggestedPhases.length>0&&x.suggestedPhases.length<=4&&x.suggestedPhases.every(p=>p&&text(p.name,100)&&list(p.items,250,12))&&Array.isArray(x.matchingProjectIds)&&x.matchingProjectIds.length<=projects.length&&new Set(x.matchingProjectIds).size===x.matchingProjectIds.length&&x.matchingProjectIds.every(id=>projects.some(p=>p.id===id))&&text(x.nextStep,500)&&(x.complexity===null||(x.complexity&&Number.isInteger(x.complexity.score)&&x.complexity.score>=1&&x.complexity.score<=10&&['low','medium','high'].includes(x.complexity.level)&&text(x.complexity.explanation,1000))));
}
export function mountBuilder({dialog,content},{projects,initial='',mode='idea',contact,focusProject,track,el,record=()=>{}}){const challenge=mode==='challenge';let step=1,type='Website',idea=initial,audienceText='';let cancelled=false;dialog.addEventListener('close',()=>cancelled=true);let controller;dialog.addEventListener('close',()=>controller?.abort());
 function typeStep(){content.replaceChildren(el('p','01 / What are we building?','os-step'));const options=el('div',undefined,'os-type-options');for(const t of ['Website','Mobile App','AI','Marketplace','Booking Platform','E-commerce','Something Crazy']){const b=el('button',t);b.type='button';b.setAttribute('aria-pressed',String(t===type));b.onclick=()=>{type=t;ideaStep()};options.append(b)}content.append(options)}
 function ideaStep(){step=2;content.replaceChildren(el('p',challenge?'01 / What is getting in your way?':`02 / Your ${type.toLowerCase()} idea`,'os-step'));const form=el('form');const label=el('label',challenge?'Describe the business problem you want to solve':'Tell me your idea in one or two sentences');const field=el('textarea');field.rows=5;field.maxLength=2000;field.minLength=10;field.required=true;field.value=idea;label.append(field);const users=el('label','Who is it for? (optional)');const audience=el('input');audience.maxLength=200;audience.value=audienceText;users.append(audience);const back=el('button','Back','os-close');back.type='button';back.onclick=()=>{idea=field.value;typeStep()};const go=el('button',challenge?'Challenge accepted — propose a system':'Create project outline','button');form.append(label,users);if(!challenge)form.append(back);form.append(go);content.append(form);field.focus();form.onsubmit=async e=>{e.preventDefault();idea=field.value;audienceText=audience.value;go.disabled=true;back.disabled=true;go.textContent='Preparing your outline…';const brief=idea+(audience.value?'\nTarget users: '+audience.value:'');let concept,ai=false,failure='';controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),60000);try{const r=await fetch(challenge?'/api/challenge':'/api/idea',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({productType:type,idea:brief}),signal:controller.signal});if(!r.ok){const error=await r.json().catch(()=>({}));throw Error(error.code|| (r.status===429?'rate_limit':'unavailable'))}const x=await r.json();if(!validConcept(x,projects))throw Error();concept=x;ai=true}catch(error){failure=error.name==='AbortError'?'timeout':error.message;concept=fallbackConcept(type,brief,projects);if(challenge){concept.projectName='Your business problem';concept.coreSystems=['Review the current workflow','Identify where the process breaks down','Agree requirements and success criteria'];concept.suggestedPhases=[{name:'Discovery',items:concept.coreSystems}];concept.matchingProjectIds=searchProjects(brief,projects).projects.map(p=>p.id)}track(challenge?'challenge_failed':'idea_builder_failed',{productType:type})}finally{clearTimeout(timeout)}if(!cancelled)result(concept,ai,failure)}}
 function result(c,ai,failure){if(!challenge&&ai)record('idea-complete');track(challenge?(ai?'challenge_completed':'challenge_fallback'):'idea_builder_completed',{productType:type,resultCount:c.matchingProjectIds.length});content.replaceChildren(el('p',ai?(challenge?'CHALLENGE ACCEPTED / PROPOSED SYSTEM':'PROJECT CONCEPT'):(challenge?'PROBLEM BRIEF':'PROJECT STARTER'),'os-step'),el('h3',c.projectName),el('p',c.summary));content.append(el('p',ai?'A starting point for discussion, not a quotation or delivery commitment.':(failure==='timeout'?'AI generation took too long.':failure==='rate_limit'?'AI is busy. Please wait a minute before retrying.':failure==='configuration'?'AI generation is temporarily unavailable while its connection is checked.':'AI generation could not complete this time.')+' Your idea is preserved below. Choose Edit my idea to retry, or continue to an enquiry.','os-notice'));content.append(el('h3','Suggested core systems'));const systems=el('ul');c.coreSystems.forEach(s=>systems.append(el('li',s)));content.append(systems);for(const phase of c.suggestedPhases){content.append(el('h3',phase.name));const ul=el('ul');phase.items.forEach(s=>ul.append(el('li',s)));content.append(ul)}content.append(el('h3','Related DevMania experience'));if(!c.matchingProjectIds.length)content.append(el('p','No close portfolio match was found. We can still discuss your idea.'));for(const id of c.matchingProjectIds){const p=projects.find(p=>p.id===id);const b=el('a',p.name,'os-related');b.href='#project-'+p.id;b.onclick=e=>{e.preventDefault();track('idea_project_match_clicked');focusProject(p)};content.append(b)}if(c.complexity){content.append(el('h3',`Build complexity: ${c.complexity.score}/10`),el('p',c.complexity.explanation));const meter=el('meter');meter.min=1;meter.max=10;meter.value=c.complexity.score;meter.setAttribute('aria-label','Build complexity');content.append(meter)}else content.append(el('p','Complexity will be assessed once the scope is reviewed.'));
 const label=el('label','Your editable project brief');const brief=el('textarea');brief.rows=8;brief.maxLength=5000;brief.value=`${c.projectName}\n\n${c.summary}\n\nSuggested systems:\n${c.coreSystems.map(x=>'- '+x).join('\n')}\n\nSuggested phases:\n${c.suggestedPhases.map(p=>p.name+': '+p.items.join(', ')).join('\n')}\n\nNext step: ${c.nextStep}`;label.append(brief);content.append(label);const go=el('button',challenge?'Build this with DevMania':'Start this project','button');go.onclick=()=>{track('start_project_clicked',{productType:type});contact(brief.value,type)};const edit=el('button',challenge?'Edit my problem':'Edit my idea','os-close');edit.onclick=ideaStep;content.append(go,edit)}
 if(challenge)ideaStep();else typeStep();
}
